#include <stdio.h>
int main(void) {
    FILE *fp = fopen("students.txt", "w");
    int roll, rc; char name[20];
    if (!fp) { perror("students.txt"); return 1; }
    if (fprintf(fp, "1 Rama\n2 Sita\n") < 0) { fclose(fp); return 1; }
    if (fclose(fp) == EOF) return 1;
    fp = fopen("students.txt", "r");
    if (!fp) return 1;
    while ((rc = fscanf(fp, "%d%19s", &roll, name)) == 2)
        printf("%d %s\n", roll, name);
    if (ferror(fp) || rc != EOF) { fclose(fp); return 1; }
    return fclose(fp) == EOF ? 1 : 0;
}

