#include <stdio.h>
#include <ctype.h>
#include <ctype.h>
int main(void) {
    char line[256]; int ch;
    unsigned long total = 0, letters = 0, digits = 0, symbols = 0, spaces = 0;
    FILE *fp;
    if (!fgets(line, sizeof line, stdin)) return 1;
    fp = fopen("count.txt", "w");
    if (!fp) return 1;
    if (fputs(line, fp) == EOF) { fclose(fp); return 1; }
    if (fclose(fp) == EOF) return 1;
    fp = fopen("count.txt", "r");
    if (!fp) return 1;
    while ((ch = fgetc(fp)) != EOF) {
        total++;
        if (isalpha((unsigned char)ch)) letters++;
        else if (isdigit((unsigned char)ch)) digits++;
        else if (isspace((unsigned char)ch)) spaces++;
        else symbols++;
    }
    if (ferror(fp)) { fclose(fp); return 1; }
    if (fclose(fp) == EOF) return 1;
    printf("Characters: %lu\nLetters: %lu\nDigits: %lu\nSpecial symbols: %lu\nWhitespace: %lu\n", total, letters, digits, symbols, spaces);
    return 0;
}

