u5-copy.code:
#include <stdio.h>
int main(void) {
    FILE *in = fopen("input.txt", "r"), *out;
    int ch, bad = 0;
    if (!in) { perror("input.txt"); return 1; }
    out = fopen("output.txt", "w");
    if (!out) { fclose(in); return 1; }
    while ((ch = fgetc(in)) != EOF)
        if (fputc(ch, out) == EOF) { bad = 1; break; }
    if (ferror(in)) bad = 1;
    if (fclose(in) == EOF) bad = 1;
    if (fclose(out) == EOF) bad = 1;
    if (bad) return 1;
    out = fopen("output.txt", "r");
    if (!out) return 1;
    while ((ch = fgetc(out)) != EOF)
        if (putchar(ch) == EOF) { fclose(out); return 1; }
    bad = ferror(out);
    if (fclose(out) == EOF) bad = 1;
    return bad ? 1 : 0;
}

