#include <stdio.h>
int main(void) {
    FILE *fp = fopen("numbers.txt", "w"), *even, *odd;
    int i, n, rc, bad = 0;
    if (!fp) return 1;
    for (i = 1; i <= 10; i++)
        if (fprintf(fp, "%d\n", i) < 0) { fclose(fp); return 1; }
    if (fclose(fp) == EOF) return 1;
    fp = fopen("numbers.txt", "r");
    if (!fp) return 1;
    even = fopen("even.txt", "w");
    if (!even) { fclose(fp); return 1; }
    odd = fopen("odd.txt", "w");
    if (!odd) { fclose(fp); fclose(even); return 1; }
    while ((rc = fscanf(fp, "%d", &n)) == 1) {
        if (fprintf(n % 2 == 0 ? even : odd, "%d\n", n) < 0) { bad = 1; break; }
        printf("%d: %s\n", n, n % 2 == 0 ? "Even" : "Odd");
    }
    if (ferror(fp) || rc != EOF) bad = 1;
    if (fclose(fp) == EOF) bad = 1;
    if (fclose(even) == EOF) bad = 1;
    if (fclose(odd) == EOF) bad = 1;
    return bad ? 1 : 0;
}

