struct item { int id; char name[20]; float price; };
int main(void) {
    struct item items[3], value;
    FILE *fp; int i;
    for (i = 0; i < 3; i++) {
        if (scanf("%d%19s%f", &items[i].id, items[i].name, &items[i].price) != 3
            || !(items[i].price >= 0 && items[i].price <= 1000000)) return 1;
    }
    fp = fopen("inventory.dat", "wb");
    if (!fp) return 1;
    if (fwrite(items, sizeof items[0], 3, fp) != 3) { fclose(fp); return 1; }
    if (fclose(fp) == EOF) return 1;
    fp = fopen("inventory.dat", "rb");
    if (!fp) return 1;
    for (i = 0; i < 3; i++) {
        if (fread(&value, sizeof value, 1, fp) != 1) { fclose(fp); return 1; }
        printf("%d %s %.2f\n", value.id, value.name, value.price);
    }
    return fclose(fp) == EOF ? 1 : 0;
}

