#include <stdio.h>
int main(void) {
    const char data[] = "ABCDEFGHIJKLMNOPQRST";
    FILE *fp = fopen("position.bin", "w+b");
    long pos; int ch;
    if (!fp) return 1;
    if (fwrite(data, 1, 20, fp) != 20) { fclose(fp); return 1; }
    if (fseek(fp, 15L, SEEK_SET) != 0 || (pos = ftell(fp)) == -1L
        || (ch = fgetc(fp)) == EOF) { fclose(fp); return 1; }
    printf("Offset %ld: %c\n", pos, ch);
    if (fseek(fp, -5L, SEEK_END) != 0 || (ch = fgetc(fp)) == EOF) { fclose(fp); return 1; }
    printf("Five before end: %c\n", ch);
    rewind(fp);
    if ((pos = ftell(fp)) != 0L || (ch = fgetc(fp)) == EOF) { fclose(fp); return 1; }
    printf("After rewind %ld: %c\n", pos, ch);
    return fclose(fp) == EOF ? 1 : 0;
}

